"use strict";
const marks = /[\u0300-\u036f\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed]/g;
const stripMarks = (value) => value.normalize("NFD").replace(marks, "").toLocaleLowerCase();
function harborEBookSearch(text) {
    const input = JSON.parse(text), paragraphs = input.paragraphs, query = input.query, current = input.current, showFutureResults = input.showFutureResults;
    const results = (() => {
        const term = stripMarks(query.trim());
        if (!term)
            return [];
        return paragraphs
            .map((text, index) => ({ text, index }))
            .filter(({ text }) => stripMarks(text).includes(term));
    })();
    const shownResults = showFutureResults
        ? results
        : results.filter((result) => result.index <= current);
    const hiddenResults = results.length - shownResults.length;
    return JSON.stringify({ shown: shownResults, hidden: hiddenResults, total: results.length });
}
